import React, { useState } from 'react';
import data from './../data/experienceData.js';

function Experience() {
  return (
    <section id="experience" className='py-20 px-6 sm:px-8 lg:px-12'>
      <div className="max-w-6xl mx-auto">
        {/* Clean Section Header */}
        <div className="text-center mb-16">
          <h2 className="text-fluid-4xl font-display font-bold text-white mb-4">
            Professional <span className="text-accent-color">Experience</span>
          </h2>
          <div className="w-24 h-1 bg-blue-600 mx-auto rounded-full mb-6"></div>
          <p className="text-muted-light text-fluid-lg max-w-2xl mx-auto leading-relaxed">
            My professional journey through innovative projects and impactful contributions
          </p>
        </div>

        {/* Timeline Experience Cards */}
        <div className="relative">
          {/* Timeline line */}
          <div className="absolute left-8 md:left-1/2 top-0 bottom-0 w-0.5 bg-gray-700 transform md:-translate-x-px"></div>

          <div className="space-y-12">
            {data.map((exp, index) => (
              <ExperienceCard key={exp.id} experience={exp} index={index} />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

// Stylish Animated Experience Card
function AnimatedExperienceCard({ experience, index }) {
  const [isExpanded, setIsExpanded] = useState(false);

  return (
    <div 
      className="group relative animate-fade-in-up hover:scale-[1.02] transition-all duration-500" 
      style={{ animationDelay: `${index * 0.2}s` }}
    >
      {/* Background glow effect */}
      <div className="absolute -inset-1 bg-gradient-to-r from-[#3B82F6]/20 via-[#60A5FA]/20 to-[#3B82F6]/20 rounded-3xl blur opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>

      {/* Main card */}
      <div className="relative glass-effect-strong rounded-3xl p-8 border border-[#3B82F6]/20 group-hover:border-[#3B82F6]/40 transition-all duration-500">

        {/* Card header with sliding animation */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between mb-6">
          <div className="flex items-start gap-6 mb-4 lg:mb-0">
            {/* Animated company logo placeholder */}
            <div className="w-16 h-16 bg-gradient-to-br from-[#3B82F6] to-[#60A5FA] rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform duration-300 shadow-lg">
              <div className="w-8 h-8 bg-white rounded-lg"></div>
            </div>

            <div className="flex-1">
              <h3 className="text-2xl font-bold text-white mb-2 group-hover:text-transparent group-hover:bg-gradient-to-r group-hover:from-[#3B82F6] group-hover:to-[#60A5FA] group-hover:bg-clip-text transition-all duration-300">
                {experience.title}
              </h3>
              <p className="text-[#3B82F6] font-semibold text-lg mb-2">{experience.org}</p>
              <div className="flex flex-wrap items-center gap-4 text-sm text-gray-400">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-[#3B82F6] rounded-full"></div>
                  <span>{experience.date}</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-[#3B82F6] rounded-full"></div>
                  <span>{experience.location}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Animated status badge */}
          <div className="flex flex-col items-start lg:items-end gap-3">
            <span className={`px-4 py-2 rounded-full text-sm font-medium shadow-lg transform group-hover:scale-105 transition-transform duration-300 ${
              experience.type === 'Full-time' 
                ? 'bg-gradient-to-r from-green-500/20 to-green-400/20 text-green-400 border border-green-400/30' 
                : experience.type === 'Internship' 
                ? 'bg-gradient-to-r from-[#3B82F6]/20 to-[#60A5FA]/20 text-[#3B82F6] border border-[#3B82F6]/30'
                : 'bg-gradient-to-r from-purple-500/20 to-purple-400/20 text-purple-400 border border-purple-400/30'
            }`}>
              {experience.type}
            </span>

            {/* Expand/Collapse button */}
            <button 
              onClick={() => setIsExpanded(!isExpanded)}
              className="flex items-center gap-2 px-4 py-2 bg-[#3B82F6]/10 hover:bg-[#3B82F6]/20 text-[#3B82F6] rounded-lg transition-all duration-300 border border-[#3B82F6]/20 hover:border-[#3B82F6]/40"
            >
              <span className="text-sm font-medium">
                {isExpanded ? 'Show Less' : 'Show More'}
              </span>
              <div className={`w-3 h-3 border-r-2 border-b-2 border-[#3B82F6] transform transition-transform duration-300 ${
                isExpanded ? 'rotate-225' : 'rotate-45'
              }`}></div>
            </button>
          </div>
        </div>

        {/* Description */}
        <p className="text-gray-300 text-base leading-relaxed mb-6 transform group-hover:translate-x-2 transition-transform duration-300">
          {experience.description}
        </p>

        {/* Expandable content with smooth animation */}
        <div className={`overflow-hidden transition-all duration-500 ease-in-out ${
          isExpanded ? 'max-h-[1000px] opacity-100' : 'max-h-0 opacity-0'
        }`}>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-6">
            {/* Responsibilities with staggered animation */}
            <div className="transform translate-y-4 opacity-0 animate-fade-in-up" style={{animationDelay: '0.1s'}}>
              <h4 className="text-white font-semibold mb-4 flex items-center gap-2">
                <div className="w-2 h-6 bg-gradient-to-b from-[#3B82F6] to-[#60A5FA] rounded-full"></div>
                Key Responsibilities
              </h4>
              <ul className="space-y-3">
                {experience.responsibilities.map((resp, idx) => (
                  <li key={idx} className="flex items-start gap-3 group/item">
                    <div className="w-2 h-2 bg-[#3B82F6] rounded-full mt-2 flex-shrink-0 group-hover/item:scale-150 transition-transform duration-200"></div>
                    <span className="text-gray-300 text-sm leading-relaxed group-hover/item:text-gray-200 transition-colors duration-200">
                      {resp}
                    </span>
                  </li>
                ))}
              </ul>
            </div>

            {/* Achievements with staggered animation */}
            <div className="transform translate-y-4 opacity-0 animate-fade-in-up" style={{animationDelay: '0.2s'}}>
              <h4 className="text-white font-semibold mb-4 flex items-center gap-2">
                <div className="w-2 h-6 bg-gradient-to-b from-[#60A5FA] to-[#3B82F6] rounded-full"></div>
                Key Achievements
              </h4>
              <ul className="space-y-3">
                {experience.achievements.map((achievement, idx) => (
                  <li key={idx} className="flex items-start gap-3 group/item">
                    <div className="w-2 h-2 bg-[#60A5FA] rounded-full mt-2 flex-shrink-0 group-hover/item:scale-150 transition-transform duration-200"></div>
                    <span className="text-gray-300 text-sm leading-relaxed group-hover/item:text-gray-200 transition-colors duration-200">
                      {achievement}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>

        {/* Technologies with animated tags */}
        <div className="transform translate-y-4 opacity-0 animate-fade-in-up" style={{animationDelay: '0.3s'}}>
          <h4 className="text-white font-semibold mb-4 flex items-center gap-2">
            <div className="w-2 h-6 bg-gradient-to-b from-[#3B82F6] to-[#60A5FA] rounded-full"></div>
            Technologies & Tools
          </h4>
          <div className="flex flex-wrap gap-3">
            {experience.technologies.map((tech, idx) => (
              <span 
                key={idx} 
                className="px-4 py-2 bg-gradient-to-r from-[#3B82F6]/10 to-[#60A5FA]/10 text-[#3B82F6] rounded-full text-sm font-medium border border-[#3B82F6]/20 hover:border-[#3B82F6]/40 hover:bg-[#3B82F6]/20 hover:scale-105 hover:-translate-y-1 transition-all duration-300 shadow-lg"
                style={{animationDelay: `${idx * 0.1}s`}}
              >
                {tech}
              </span>
            ))}
          </div>
        </div>

        {/* Animated corner decorations */}
        <div className="absolute top-4 right-4 w-6 h-6 border-r-2 border-t-2 border-[#3B82F6]/20 opacity-0 group-hover:opacity-100 group-hover:scale-150 transition-all duration-500"></div>
        <div className="absolute bottom-4 left-4 w-6 h-6 border-l-2 border-b-2 border-[#60A5FA]/20 opacity-0 group-hover:opacity-100 group-hover:scale-150 transition-all duration-500"></div>
      </div>
    </div>
  );
}

export default Experience;
